59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
76	    private static final int MAX_OWNERS_PER_CITY = 50;
77	
78	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
79	    private static final int MAX_OWNERS_PER_DAY = 100;
80	
81	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
82	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    private final TelephoneNormalizer telephoneNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper,
100	                                 TelephoneNormalizer telephoneNormalizer,
101	                                 AddressNormalizer addressNormalizer) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneNormalizer = telephoneNormalizer;
107	        this.addressNormalizer = addressNormalizer;
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
113	        Collection<Owner> owners;
114	        if (lastName != null) {
115	            owners = this.clinicService.findOwnerByLastName(lastName);
116	        } else {
117	            owners = this.clinicService.findAllOwners();
118	        }
119	        if (owners.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        owners.forEach(this::populateHouseholdMemberCount);
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        populateHouseholdMemberCount(owner);
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        normalizeAndValidate(ownerFieldsDto);
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
144	        owner.setNamesakeCount(countNamesakes(owner));
145	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
146	        assignHousehold(owner, ownerFieldsDto);
147	        this.clinicService.saveOwner(owner);
148	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
149	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
150	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
151	        populateHouseholdMemberCount(owner);
152	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
153	        headers.setLocation(UriComponentsBuilder.newInstance()
154	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
155	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
156	    }
157	
158	    /**
159	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
160	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
161	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
162	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
163	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
164	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
165	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
166	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
167	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
168	     *
169	     * @param ownerFieldsDto the incoming owner payload, mutated in place
170	     * @throws MissingOwnerFieldsException if any required field is missing or blank
171	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
172	     */
173	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
174	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
175	        validateRequiredFields(ownerFieldsDto);
176	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
177	        ownerFieldsDto.setTelephone(telephone);
178	        requireUniqueTelephone(telephone);
179	        requireUniqueHousehold(ownerFieldsDto);
180	        requireCityHasCapacity(ownerFieldsDto.getCity());
181	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
182	        ownerFieldsDto.setRegistrationDate(registrationDate);
183	        requireDailyLimitNotReached(registrationDate);
184	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
185	    }
186	
187	    /**
188	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
189	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
190	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
191	     *
192	     * @param ownerFieldsDto the incoming owner payload
193	     * @return the effective registration date rolled forward onto a business day
194	     */
195	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
196	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
197	        if (effective == null) {
198	            effective = LocalDate.now();
199	        }
200	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
201	            effective = effective.plusDays(1);
202	        }
203	        return effective;
204	    }
205	
206	    /**
207	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
208	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
209	     * further owner may be created for that day.
210	     *
211	     * @param registrationDate the adjusted business-day registration date of the owner being created
212	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
213	     */
214	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
215	        long createdThatDay = this.clinicService.findAllOwners().stream()
216	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
217	            .count();
218	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
219	            throw new DailyOwnerLimitExceededException(
220	                "the maximum number of owners for today has already been reached");
221	        }
222	    }
223	
224	    /**
225	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
226	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
227	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
228	     * reflects only owners that predate it.
229	     *
230	     * @param registrationDate the adjusted business-day registration date of the owner being created
231	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
232	     */
233	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
234	        long createdThatDay = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
236	            .count();
237	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
238	    }
239	
240	    /**
241	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
242	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
243	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
244	     * city (e.g. {@code LON-SMI-0007}).
245	     *
246	     * @param city     the owner's city
247	     * @param lastName the owner's last name
248	     * @return the generated customer code
249	     */
250	    private String generateCustomerCode(String city, String lastName) {
251	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
252	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
253	        int sequence = (int) this.clinicService.findAllOwners().stream()
254	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
255	            .count() + 1;
256	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
257	    }
258	
259	    /**
260	     * Counts how many existing owners already share the given owner's first and last name, compared
261	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
262	     * create; it is zero when the owner's name is unique.
263	     *
264	     * @param owner the newly mapped owner about to be saved
265	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
266	     */
267	    private int countNamesakes(Owner owner) {
268	        String firstName = owner.getFirstName();
269	        String lastName = owner.getLastName();
270	        return (int) this.clinicService.findAllOwners().stream()
271	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
272	                && lastName.equalsIgnoreCase(existing.getLastName()))
273	            .count();
274	    }
275	
276	    /**
277	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
278	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
279	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
280	     *
281	     * @param ownerFieldsDto the owner payload to validate
282	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
283	     */
284	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
285	        List<String> missingFields = new ArrayList<>();
286	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
287	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
288	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
289	        requireText(missingFields, "city", ownerFieldsDto.getCity());
290	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
291	        if (!missingFields.isEmpty()) {
292	            throw new MissingOwnerFieldsException(missingFields);
293	        }
294	    }
295	
296	    private void requireText(List<String> missingFields, String fieldName, String value) {
297	        if (value == null || value.isBlank()) {
298	            missingFields.add(fieldName);
299	        }
300	    }
301	
302	    /**
303	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
304	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
305	     * (blank or {@code null}) email is left untouched, since the field is optional.
306	     *
307	     * @param email the raw email value from the request, may be {@code null}
308	     * @return the lower-cased email, or the original value when none was supplied
309	     */
310	    private String normalizeEmail(String email) {
311	        if (email == null || email.isBlank()) {
312	            return email;
313	        }
314	        return email.toLowerCase();
315	    }
316	
317	    /**
318	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
319	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
320	     * originally formatted.
321	     *
322	     * @param telephone the normalized telephone of the owner being created
323	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
324	     */
325	    private void requireUniqueTelephone(String telephone) {
326	        boolean inUse = this.clinicService.findAllOwners().stream()
327	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
328	            .anyMatch(telephone::equals);
329	        if (inUse) {
330	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
331	        }
332	    }
333	
334	    /**
335	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
336	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
337	     *
338	     * @param city the city of the owner being created
339	     * @throws OwnerCityFullException if the city already contains 50 or more owners
340	     */
341	    private void requireCityHasCapacity(String city) {
342	        long cityOwners = this.clinicService.findAllOwners().stream()
343	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
344	            .count();
345	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
346	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
347	        }
348	    }
349	
350	    /**
351	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
352	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
353	     *
354	     * @param ownerFieldsDto the incoming owner payload
355	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
356	     *                                 set {@code sharesHousehold}
357	     */
358	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
359	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
360	            return;
361	        }
362	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
363	            throw new DuplicateOwnerException(
364	                "an owner with the same last name and address already exists in this household");
365	        }
366	    }
367	
368	    /**
369	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
370	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
371	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
372	     * incidental formatting differences and abbreviation variants do not affect membership.
373	     *
374	     * @param ownerFieldsDto the incoming owner payload
375	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
376	     *         them; empty when none match
377	     */
378	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
379	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
380	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
381	        return this.clinicService.findAllOwners().stream()
382	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
383	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
384	            .toList();
385	    }
386	
387	    /**
388	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
389	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
390	     *
391	     * @param value the raw field value, may be {@code null}
392	     * @return the whitespace-collapsed value, or an empty string when {@code null}
393	     */
394	    private String collapseWhitespace(String value) {
395	        if (value == null) {
396	            return "";
397	        }
398	        return value.strip().replaceAll("\\s+", " ");
399	    }
400	
401	    /**
402	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
403	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
404	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
405	     * identifier is derived deterministically from the household's last name and address, so every member of the same
406	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
407	     * feature and still lack the identifier are backfilled so the whole household shares it.
408	     *
409	     * @param owner          the newly mapped owner about to be saved
410	     * @param ownerFieldsDto the incoming owner payload
411	     */
412	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
413	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
414	            return;
415	        }
416	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
417	        if (members.isEmpty()) {
418	            return;
419	        }
420	        String householdId = generateHouseholdId(ownerFieldsDto);
421	        owner.setHouseholdId(householdId);
422	        for (Owner member : members) {
423	            if (!householdId.equals(member.getHouseholdId())) {
424	                member.setHouseholdId(householdId);
425	                this.clinicService.saveOwner(member);
426	            }
427	        }
428	    }
429	
430	    /**
431	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
432	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
433	     * of those fields, it is identical for every owner in the same household and never changes over time.
434	     *
435	     * @param ownerFieldsDto the incoming owner payload
436	     * @return the household identifier
437	     */
438	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
439	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
440	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
441	        try {
442	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
443	            StringBuilder hex = new StringBuilder();
444	            for (int i = 0; i < 6; i++) {
445	                hex.append(String.format("%02X", digest[i]));
446	            }
447	            return "HH-" + hex;
448	        } catch (NoSuchAlgorithmException ex) {
449	            throw new IllegalStateException("SHA-256 is not available", ex);
450	        }
451	    }
452	
453	    /**
454	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
455	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
456	     * household is counted as a household of one.
457	     *
458	     * @param owner the owner whose household size should be resolved
459	     */
460	    private void populateHouseholdMemberCount(Owner owner) {
461	        String householdId = owner.getHouseholdId();
462	        if (householdId == null) {
463	            owner.setHouseholdMemberCount(1);
464	            return;
465	        }
466	        long members = this.clinicService.findAllOwners().stream()
467	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
468	            .count();
469	        owner.setHouseholdMemberCount((int) members);
470	    }
471	
472	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
473	    @Override
474	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
475	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
476	        if (currentOwner == null) {
477	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
478	        }
479	        currentOwner.setAddress(ownerFieldsDto.getAddress());
480	        currentOwner.setCity(ownerFieldsDto.getCity());
481	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
482	        currentOwner.setLastName(ownerFieldsDto.getLastName());
483	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
484	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
485	        this.clinicService.saveOwner(currentOwner);
486	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
487	    }
488	
489	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
490	    @Transactional
491	    @Override
492	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
493	        Owner owner = this.clinicService.findOwnerById(ownerId);
494	        if (owner == null) {
495	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
496	        }
497	        this.clinicService.deleteOwner(owner);
498	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
499	    }
500	
501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
504	        Owner owner = this.clinicService.findOwnerById(ownerId);
505	        if (owner == null) {
506	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
507	        }
508	        HttpHeaders headers = new HttpHeaders();
509	        Pet pet = petMapper.toPet(petFieldsDto);
510	        owner.setId(ownerId);
511	        pet.setOwner(owner);
512	        pet.getType().setName(null);
513	        this.clinicService.savePet(pet);
514	        PetDto petDto = petMapper.toPetDto(pet);
515	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
516	            .buildAndExpand(pet.getId()).toUri());
517	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
518	    }
519	
520	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
